SINA_SMART["anat2-spleen"] = {"lecture":"anat2-spleen","title":"The spleen","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat2-spleen:e0","text":"Spleen: 10-12 cm, 150-200 g; intraperitoneal except hilum.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-spleen:e1","text":"Largest lymphoid mass: immune surveillance.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-spleen:e2","text":"Left hypochondrium, against ribs 9-11, long axis along rib 10.","topic":"Position and relations","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-spleen:e3","text":"Normally not palpable below the costal margin.","topic":"Position and relations","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-spleen:e4","text":"Surfaces: diaphragmatic and visceral; hilum.","topic":"Position and relations","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-spleen:e5","text":"7 ligaments: gastrosplenic (short gastrics), splenorenal (splenic vessels + pancreatic tail), splenophrenic, splenocolic, phrenicocolic, pancreaticosplenic, pancreaticocolic.","topic":"Ligaments","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-spleen:e6","text":"Splenic artery: largest coeliac branch, along upper pancreas.","topic":"Vessels, nerves and surgery","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-spleen:e7","text":"Segmental branching allows partial splenectomy.","topic":"Vessels, nerves and surgery","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-spleen:e8","text":"Splenic vein behind pancreas + SMV → portal vein.","topic":"Vessels, nerves and surgery","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-spleen:e9","text":"Lymph to coeliac/SMA nodes; nerves from vagus and splanchnics.","topic":"Vessels, nerves and surgery","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"biez7k":"a","1gacab2":"a","13ozd73":"a","fso8m5":"a","1lxtzk4":"a","1sf93gi":"a","5od0fj":"a","kpuy9f":"a","18z3cgx":"a","181hpye":"a","qgg8lm":"a"},"mapCounts":{"verified":0,"auto":11,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat2-spleen:e0":{"s":0,"u":["Spleen: 10-12 cm, 150-200 g; intraperitoneal except hilum.","It is intraperitoneal , suspended by peritoneal folds; only the hilum is bare.","An ovoid, soft, purplish, pulpy organ with a thin capsule, normally 10-12 cm and 150-200 g in adults (very variable)."],"dp":[]},"anat2-spleen:e1":{"s":0,"u":["Largest lymphoid mass: immune surveillance.","It is the largest mass of lymphoid tissue : lymphocyte proliferation, immune surveillance and defence."],"dp":[]},"anat2-spleen:e2":{"s":1,"u":["Left hypochondrium, against ribs 9-11, long axis along rib 10.","It lies against the left 9th-11th ribs , its long axis parallel to the 10th rib , separated from them by the diaphragm and the costodiaphragmatic recess (so rib fractures can injure lung, pleura and spleen)."],"dp":[{"h":"Memory aid","t":"1, 3, 5, 7, 9, 11 : about 1 × 3 × 5 inches, ~7 oz (150-200 g), lies under ribs 9 to 11 (long axis along rib 10)."},{"h":"Clinical","t":"Left lower rib fractures can rupture the spleen → haemorrhage and Kehr's sign (left shoulder pain via the phrenic nerve). The pancreatic tail is at risk during splenectomy."}]},"anat2-spleen:e3":{"s":1,"u":["Normally not palpable below the costal margin.","In the superolateral left hypochondrium , protected by the lower thoracic cage and not normally descending below the costal margin (a palpable spleen is abnormal); it moves with breathing."],"dp":[{"h":"Note","t":"Intraperitoneal (except the hilum), in the left hypochondrium; not normally palpable . When enlarged it grows down and towards the right iliac fossa , with a palpable notch on its anterior border."}]},"anat2-spleen:e4":{"s":1,"u":["Surfaces: diaphragmatic and visceral; hilum.","Two surfaces: diaphragmatic (related to the recess and lower left lung) and visceral (left colic flexure, pancreatic tail, stomach, kidney), with the hilum transmitting splenic vessels, nerves and lymphatics."],"dp":[]},"anat2-spleen:e5":{"s":2,"u":["7 ligaments: gastrosplenic (short gastrics), splenorenal (splenic vessels + pancreatic tail), splenophrenic, splenocolic, phrenicocolic, pancreaticosplenic, pancreaticocolic.","Seven peritoneal ligaments: gastrosplenic (short gastric and left gastroepiploic vessels), splenophrenic , splenorenal (splenic vessels and tail of the pancreas ), pancreaticosplenic , pancreaticocolic (mesocolon), splenocolic and phrenicocolic (parts of the greater omentum)."],"dp":[{"h":"Note","t":"Gastrosplenic ligament = short gastric + left gastroepiploic vessels; splenorenal ligament = splenic vessels + tail of the pancreas ."}]},"anat2-spleen:e6":{"s":3,"u":["Splenic artery: largest coeliac branch, along upper pancreas.","The splenic artery , the largest branch of the coeliac trunk , runs a tortuous course along the upper border of the pancreas, behind the lesser sac and in front of the left kidney, then in the splenorenal ligament, dividing into 2-3 branches before the hilum."],"dp":[{"h":"Note","t":"Splenic artery = largest coeliac branch, tortuous , along the upper border of the pancreas; divides into segmental branches (partial splenectomy possible). Splenic vein + SMV → portal vein ."}]},"anat2-spleen:e7":{"s":3,"u":["Segmental branching allows partial splenectomy.","Its segmental branching allows partial (segmental) splenectomy and distal pancreatectomy with spleen preservation."],"dp":[]},"anat2-spleen:e8":{"s":3,"u":["Splenic vein behind pancreas + SMV → portal vein.","The splenic vein leaves the hilum, runs behind the pancreas and joins the SMV to form the portal vein (splenic vein thrombosis causes gastric varices)."],"dp":[]},"anat2-spleen:e9":{"s":3,"u":["Lymph to coeliac/SMA nodes; nerves from vagus and splanchnics.","Lymph goes to coeliac and superior mesenteric nodes; nerves come from the vagus and splanchnic nerves."],"dp":[]}},"meta":{"biez7k":{"a":"recall","vg":"anat2-spleen:e0/recall/1"},"1gacab2":{"a":"recall","vg":"anat2-spleen:e0/recall/2"},"13ozd73":{"a":"recall","vg":"anat2-spleen:e2/recall/1"},"fso8m5":{"a":"recall","vg":"anat2-spleen:e3/recall/1"},"1lxtzk4":{"a":"recall","vg":"anat2-spleen:e5/recall/1"},"1sf93gi":{"a":"recall","vg":"anat2-spleen:e5/recall/2"},"5od0fj":{"a":"recall","vg":"anat2-spleen:e6/recall/1"},"kpuy9f":{"a":"recall","vg":"anat2-spleen:e6/recall/2"},"18z3cgx":{"a":"recall","vg":"anat2-spleen:e7/recall/1"},"181hpye":{"a":"recall","vg":"anat2-spleen:e8/recall/1"},"qgg8lm":{"a":"recall","vg":"anat2-spleen:e2/recall/2"}},"explRev":"d9fcdff0235c"};
